contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take one param: deposit amount to send to c via addToBalance. The function is payable so the test harness
    // can fund this contract before calling run.
    function run(uint256 deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);

        // Record contract and user balance before deposit
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // Try to deposit 'deposit' wei into c for this contract's address
        bool depositReverted;
        c.addToBalance{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depositReverted = true;
        } else {
            depositReverted = false;
        }

        // Read balances after deposit attempt
        uint256 midContractBal = address(c).balance;
        uint256 midUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // Attempt withdraw and observe revert
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // Read balances after withdraw attempt
        uint256 afterContractBal = address(c).balance;
        uint256 afterUserBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        // If withdraw did not revert, then recorded user balance for this contract must be zero afterwards,
        // and the contract's ETH balance must have decreased by at least the amount that was recorded for the user
        // immediately before the withdraw (midUserBal).
        assert(withdrawReverted || (afterUserBal == 0 && midContractBal >= afterContractBal && (midContractBal - afterContractBal) >= midUserBal));
    }

    // accept ETH when c withdraws to this test contract
    receive() external payable {}
}

