// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUserBal = __r; } catch { return; }
        bool depositReverted;
        try c.addToBalance{value: deposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }
        uint256 midContractBal = address(c).balance;
        uint256 midUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { midUserBal = __r; } catch { return; }
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterContractBal = address(c).balance;
        uint256 afterUserBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUserBal = __r; } catch { return; }
        assertTrue(withdrawReverted || (afterUserBal == 0 && midContractBal >= afterContractBal && (midContractBal - afterContractBal) >= midUserBal));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
